import json


def load_stock(path):
    try:
        with open(path) as fh:
            data = json.load(fh)
    except FileNotFoundError:
        return {}
    return {row['sku']: row['qty'] for row in data}


def main():
    stock = load_stock('stock.json')
    print(len(stock))
